REPLACE INTO `item_db_re` (`id`,`name_aegis`,`name_english`,`type`,`price_buy`,`weight`,`defense`,`slots`,`location_head_top`,`armor_level`,`equip_level_min`,`refineable`,`view`,`script`) VALUES (19102,'Pale_Moon_Hat','Pale Moon Hat','Armor',20,500,2,1,true,1,30,true,913,'bonus bFlee,20;\nbonus2 bAddRace2,RC2_THANATOS,5;\nbonus2 bSubRace2,RC2_THANATOS,5;\nbonus2 bMagicAddRace2,RC2_THANATOS,5;\nif (getrefine()>4) {\n   bonus2 bAddRace2,RC2_THANATOS,10;\n   bonus2 bSubRace2,RC2_THANATOS,10;\n   bonus2 bMagicAddRace2,RC2_THANATOS,10;\n}\nif (getrefine()>6) {\n   bonus2 bAddRace2,RC2_THANATOS,15;\n   bonus2 bSubRace2,RC2_THANATOS,15;\n   bonus2 bMagicAddRace2,RC2_THANATOS,15;\n}\nif (getrefine()>8) {\n   bonus2 bAddRace2,RC2_THANATOS,20;\n   bonus2 bSubRace2,RC2_THANATOS,20;\n   bonus2 bMagicAddRace2,RC2_THANATOS,20;\n}\nskill "ALL_THANATOS_RECALL",1;');
REPLACE INTO `item_db_re` (`id`,`name_aegis`,`name_english`,`type`,`weight`,`defense`,`location_head_mid`,`armor_level`,`equip_level_min`,`view`,`script`) VALUES (19104,'YDragon_SkyWing','Dragon Emperor\'s Wing','Armor',100,7,true,1,50,1413,'if (BaseClass == Job_Swordman) {\n   bonus2 bSubSize,Size_Medium,3;\n   bonus2 bSubSize,Size_Large,5;\n}\nelse if (BaseClass == Job_Mage)\n   bonus2 bSubEle,Ele_All,5;\nelse if (BaseClass == Job_Archer)\n   bonus bLongAtkDef,10;\nelse if (BaseClass == Job_Acolyte)\n   bonus bHealPower,10;\nelse if (BaseClass == Job_Thief) {\n   bonus bFlee,10;\n   bonus bFlee2,3;\n}\nelse if (BaseClass == Job_Merchant) {\n   bonus2 bSubClass,Class_Normal,3;\n   bonus2 bSubClass,Class_Boss,5;\n}\nelse if (BaseClass == Job_Novice || BaseClass == Job_Taekwon || Class == Job_Ninja || Class == Job_Gunslinger) {\n   bonus bMaxHP,1000;\n   bonus bMaxSP,100;\n}');
REPLACE INTO `item_db_re` (`id`,`name_aegis`,`name_english`,`type`,`weight`,`defense`,`slots`,`location_head_top`,`location_head_mid`,`location_head_low`,`armor_level`,`equip_level_min`,`refineable`,`view`,`script`) VALUES (19106,'Magicstone_Of_Grace','Blessing of Gemstone','Armor',3000,15,1,true,true,true,1,60,true,1420,'.@r = getrefine();\nbonus bUnbreakableHelm;\nbonus bNoGemStone;\nbonus bMatk,readparam(bInt);\nbonus bUseSPrate,100;\nif (.@r >= 5) {\n   bonus bUseSPrate,-25;\n   bonus bMatkRate,3;\n   bonus bHealPower,3;\n}\nif (.@r >= 7) {\n   bonus bUseSPrate,-25;\n   bonus bMatkRate,5;\n   bonus bHealPower,5;\n}\nif (.@r >= 9) {\n   bonus bUseSPrate,-25;\n   bonus bMatkRate,7;\n   bonus bHealPower,7;\n}');
REPLACE INTO `item_db_re` (`id`,`name_aegis`,`name_english`,`type`,`weight`,`defense`,`slots`,`location_head_top`,`location_head_low`,`armor_level`,`equip_level_min`,`refineable`,`view`,`script`) VALUES (19107,'Mad_Hatter','Mad Hatter','Armor',800,12,1,true,true,1,60,true,1421,'.@r = getrefine();\n.@per = ((.@r>=7)?10000:(.@r>=5?5000:2000));\nbonus bUnbreakableHelm;\nbonus2 bSubSkill,"NPC_CRITICALSLASH",((.@r>=7)?100:(.@r>=5?50:20));\nbonus2 bSubEle,Ele_Dark,5*.@r;\nif (BaseJob == Job_Novice)\n   bonus2 bResEff,Eff_Freeze,.@per;\nelse if (BaseJob == Job_Swordman)\n   bonus2 bResEff,Eff_Curse,.@per;\nelse if (BaseJob == Job_Mage)\n   bonus2 bResEff,Eff_Bleeding,.@per;\nelse if (BaseJob == Job_Archer)\n   bonus2 bResEff,Eff_Sleep,.@per;\nelse if (BaseJob == Job_Acolyte)\n   bonus2 bResEff,Eff_Stone,.@per;\nelse if (BaseJob == Job_Thief)\n   bonus2 bResEff,Eff_Blind,.@per;\nelse if (BaseJob == Job_Merchant)\n   bonus2 bResEff,Eff_Poison,.@per;\nelse if (BaseJob == Job_Taekwon)\n   bonus2 bResEff,Eff_Stun,.@per;\nelse if (BaseJob == Job_Ninja)\n   bonus2 bResEff,Eff_Silence,.@per;\nelse if (BaseJob == Job_Gunslinger)\n   bonus2 bResEff,Eff_Confusion,.@per;');
REPLACE INTO `item_db_re` (`id`,`name_aegis`,`name_english`,`type`,`weight`,`defense`,`slots`,`location_head_top`,`armor_level`,`equip_level_min`,`refineable`,`view`,`script`) VALUES (19108,'Wild_Poring_Rider','Wild Poring Rider','Armor',1000,9,1,true,1,30,true,1422,'if ((eaclass()&EAJ_UPPERMASK) == EAJ_KNIGHT)\n   bonus2 bAddMonsterDropItemGroup,IG_RUNE_CRAFT_MATERIALS,100;\nelse if ((eaclass()&EAJ_UPPERMASK) == EAJ_CRUSADER)\n   bonus2 bAddMonsterDropItemGroup,IG_JUICE,100;\nelse if ((eaclass()&EAJ_UPPERMASK) == EAJ_PRIEST)\n   bonus2 bAddMonsterDropItem,523,100;\nelse if ((eaclass()&EAJ_UPPERMASK) == EAJ_MONK)\n   bonus2 bAddMonsterDropItem,605,100;\nelse if ((eaclass()&EAJ_UPPERMASK) == EAJ_WIZARD)\n   bonus2 bAddMonsterDropItemGroup,IG_GEMSTONE,100;\nelse if ((eaclass()&EAJ_UPPERMASK) == EAJ_SAGE)\n   bonus2 bAddMonsterDropItemGroup,IG_ELEMENTAL_CONVERTER,100;\nelse if ((eaclass()&EAJ_UPPERMASK) == EAJ_ASSASSIN)\n   bonus2 bAddMonsterDropItemGroup,IG_POISONS,100;\nelse if ((eaclass()&EAJ_UPPERMASK) == EAJ_ROGUE || (eaclass()&EAJ_UPPERMASK) == EAJ_SUPER_NOVICE)\n   bonus2 bAddMonsterDropItem,23660,100;\nelse if ((eaclass()&EAJ_UPPERMASK) == EAJ_HUNTER || (eaclass()&EAJ_UPPERMASK) == EAJ_BARDDANCER)\n   bonus2 bAddMonsterDropItemGroup,IG_QUIVER,100;\nelse if ((eaclass()&EAJ_UPPERMASK) == EAJ_BLACKSMITH)\n   bonus2 bAddMonsterDropItemGroup,IG_BLACKSMITH,100;\nelse if ((eaclass()&EAJ_UPPERMASK) == EAJ_ALCHEMIST)\n   bonus2 bAddMonsterDropItemGroup,IG_POTION_CRAFT_MATERIALS,100;\nelse if ((eaclass()&EAJ_UPPERMASK) == EAJ_NINJA)\n   bonus2 bAddMonsterDropItemGroup,IG_KUNAI_BOX,100;\nelse if ((eaclass()&EAJ_UPPERMASK) == EAJ_GUNSLINGER)\n   bonus2 bAddMonsterDropItemGroup,IG_BULLET_CASE,100;\nelse if ((eaclass()&EAJ_UPPERMASK) == EAJ_SOUL_LINKER)\n   bonus2 bAddMonsterDropItemGroup,IG_SOUL_LINKER,100;\nelse if ((eaclass()&EAJ_UPPERMASK) == EAJ_STAR_GLADIATOR)\n   bonus2 bAddMonsterDropItemGroup,IG_ELEMENTAL_STONES,100;\nelse\n   bonus2 bAddMonsterDropItem,522,100;');
