REPLACE INTO `item_db_re` (`id`,`name_aegis`,`name_english`,`type`,`price_buy`,`weight`,`defense`,`slots`,`location_garment`,`armor_level`,`equip_level_min`,`refineable`,`script`) VALUES (20814,'Wakwak_Manteau','Wakwak Manteau','Armor',20,400,40,1,true,1,100,true,'bonus2 bAddRace,RC_All,5;\n.@s = readparam(bStr);\n.@r = getrefine();\nif (.@r>=5) {\n   bonus bBaseAtk,2*(.@s/10);\n}\nif (.@r>=7) {\n   bonus bBaseAtk,3*(.@s/10);\n}');
REPLACE INTO `item_db_re` (`id`,`name_aegis`,`name_english`,`type`,`weight`,`defense`,`slots`,`location_garment`,`armor_level`,`equip_level_min`,`refineable`,`script`) VALUES (20815,'SeraphimRobe','Seraphim Robe','Armor',300,18,1,true,1,1,true,'bonus bMaxHPrate,10;\nbonus2 bMagicAtkEle,Ele_Neutral,5;\n.@r = getrefine();\n.@s = getskilllv("CR_TRUST");\nif (.@r > 6) {\n   bonus2 bSubEle,Ele_Dark,20;\n   bonus2 bSubEle,Ele_Holy,20;\n   bonus2 bMagicAtkEle,Ele_Neutral,10;\n}\nif (.@r > 8) {\n   bonus2 bSubEle,Ele_Dark,10;\n   bonus2 bSubEle,Ele_Holy,10;\n   bonus bVariableCastrate,-5;\n}\nif (.@s > 0) {\n   bonus2 bSubEle,Ele_Holy,-.@s*3;\n}');
REPLACE INTO `item_db_re` (`id`,`name_aegis`,`name_english`,`type`,`weight`,`defense`,`slots`,`location_garment`,`armor_level`,`equip_level_min`,`refineable`,`script`) VALUES (20816,'Yoichi_Muffler','Yoichi\'s Shawl','Armor',300,18,1,true,1,100,true,'.@r = getrefine();\nbonus bMdef,10;\nbonus bAspdRate,5;\nif (getskilllv("RA_AIMEDBOLT") == 10)\n   bonus2 bSkillAtk,"RA_AIMEDBOLT",5;\nif (getskilllv("SN_SHARPSHOOTING") == 5)\n   bonus2 bSkillAtk,"SN_SHARPSHOOTING",60;\nif (getskilllv("HT_BLITZBEAT") == 5)\n   bonus2 bSkillAtk,"HT_BLITZBEAT",15;\nif (Class == Job_Ranger) {\n   bonus bMaxHPrate,5;\n   bonus bLongAtkDef,20;\n   if (.@r>=7) {\n      bonus bLongAtkDef,15;\n      bonus bMaxHPrate,5;\n   }\n}\nif (.@r>=7) {\n   bonus bAspdRate,3;\n   bonus2 bSkillAtk,"SN_SHARPSHOOTING",(BaseLevel/3);\n   bonus2 bSkillAtk,"HT_BLITZBEAT",(BaseLevel/5);\n   bonus2 bSkillAtk,"RA_AIMEDBOLT",(BaseLevel/30);\n}\nif (.@r>=9) {\n   bonus bAspdRate,3;\n   bonus bMaxSPrate,5;\n}');
REPLACE INTO `item_db_re` (`id`,`name_aegis`,`name_english`,`type`,`weight`,`defense`,`slots`,`location_garment`,`armor_level`,`equip_level_min`,`refineable`,`view`,`script`) VALUES (20817,'Diffusion_Bravery_Bag','[Katsua]Adventurer\'s Backpack','Armor',200,20,1,true,1,99,true,2,'.@r = getrefine();\nskill "BS_GREED",1;\nif (.@r>=7) {\n   if (readparam(bStr)>=90)\n      bonus bBaseAtk,(.@r>=9)?30:20;\n   if (readparam(bInt)>=90)\n      bonus bMatk,(.@r>=9)?50:30;\n   if (readparam(bVit)>=90)\n      bonus2 bSubEle,Ele_Neutral,(.@r>=9)?10:5;\n   if (readparam(bAgi)>=90) {\n   bonus bAspdRate,8;\n      if (.@r>=9)\n   bonus bAspd,1;\n}\n   if (readparam(bDex)>=90)\n      bonus bLongAtkRate,(.@r>=9)?10:5;\n   if (readparam(bLuk)>=90)\n      bonus bCritAtkRate,(.@r>=9)?15:10;\n}');
