REPLACE INTO `item_db_re` (`id`,`name_aegis`,`name_english`,`type`,`weight`,`location_garment`,`armor_level`,`equip_level_min`,`refineable`,`trade_noauction`,`script`) VALUES (20834,'Manteau_Of_Vagabond','Drifter\'s Cape','Armor',400,true,1,100,true,true,'.@r = getrefine();\n.@bonus = 20;\nif (.@r>=7) {\n   .@bonus += 5;\n}\nif (.@r>=9) {\n   .@bonus += 5;\n}\nbonus2 bSubEle,Ele_Neutral,.@bonus;');
REPLACE INTO `item_db_re` (`id`,`name_aegis`,`name_english`,`type`,`weight`,`defense`,`slots`,`location_garment`,`armor_level`,`equip_level_min`,`refineable`,`view`,`script`) VALUES (20835,'K_Fallen_Angel_Wing','[Katsuya] Fallen Angel Wings','Armor',200,18,1,true,1,99,true,3,'bonus bAllStats,1;\nbonus bBaseAtk,readparam(bStr)/20;\nbonus bMatk,readparam(bInt)/20;\nbonus2 bSubEle,Ele_Neutral,readparam(bVit)/20;\nbonus bLongAtkRate,readparam(bDex)/20;\nbonus bCritAtkRate,readparam(bLuk)/20;');
REPLACE INTO `item_db_re` (`id`,`name_aegis`,`name_english`,`type`,`price_buy`,`weight`,`defense`,`slots`,`location_garment`,`armor_level`,`equip_level_min`,`refineable`,`script`) VALUES (20836,'Skin_Of_Lindwurm','Skin of Lindwyrm','Armor',1000,600,15,1,true,1,100,true,'bonus bAgiVit,5;\nbonus bMdef,10;\nbonus2 bSubEle,Ele_Fire,5;\nbonus2 bSubEle,Ele_Water,5;\nbonus2 bSubRace,RC_Dragon,5;\nbonus2 bSubRace,RC_DemiHuman,5;\nbonus2 bSubRace,RC_Player_Human,5;\n.@r = getrefine();\n.@val = (readparam(bAgi)+readparam(bVit))/20;\nif (.@r>=7) {\n   skill "TF_HIDING",1;\n   if (.@r>=8) {\n      bonus bMaxHPrate,.@val;\n      bonus bVariableCastrate,-2*.@val;\n      if (.@r>=9) {\n         skill "AS_CLOAKING",1;\n      }\n   }\n}');
REPLACE INTO `item_db_re` (`id`,`name_aegis`,`name_english`,`type`,`price_buy`,`weight`,`defense`,`slots`,`location_garment`,`armor_level`,`equip_level_min`,`refineable`,`script`) VALUES (20837,'Skin_Of_Gwiber','Skin of Gwiber','Armor',20,600,15,1,true,1,100,true,'bonus bInt,5;\nbonus bDex,5;\nbonus bMdef,10;\nbonus2 bSubEle,Ele_Dark,5;\nbonus2 bSubEle,Ele_Undead,5;\nbonus2 bSubRace,RC_Demon,5;\nbonus2 bSubRace,RC_Undead,5;\n.@r = getrefine();\n.@val = (readparam(bInt)+readparam(bDex))/20;\nif (.@r>=7) {\n   bonus bSPGainValue,10;\n   if (.@r>=8) {\n      bonus bBaseAtk,5*.@val;\n      bonus bDelayrate,-1*.@val;\n      if (.@r>=9) {\n         bonus bSPGainValue,10;\n      }\n   }\n}');
