REPLACE INTO `item_db_re` (`id`,`name_aegis`,`name_english`,`type`,`price_buy`,`weight`,`defense`,`slots`,`location_armor`,`armor_level`,`equip_level_min`,`refineable`,`script`) VALUES (450010,'Europa_Robe_J','Europa Robe','Armor',200000,500,35,1,true,1,100,true,'.@r = getrefine();\n.@a = (readparam(bVit)+readparam(bLuk))/10;\nbonus bMdef,10;\nbonus bVit,5;\nbonus bLuk,5;\nbonus bDelayrate,-10;\nif (.@r>=7) {\n   bonus2 bSubRace,RC_Player_Human,7;\n   bonus2 bSubRace,RC_Player_Doram,7;\n   bonus bUnbreakableArmor;\n}\nif (.@r>=8) {\n   bonus bBaseAtk,10*.@a;\n   bonus bMatk,10*.@a;\n}\nif (.@r>=9)\n   bonus2 bResEff,Eff_Stone,10000;');
REPLACE INTO `item_db_re` (`id`,`name_aegis`,`name_english`,`type`,`price_buy`,`weight`,`defense`,`slots`,`location_armor`,`armor_level`,`refineable`,`script`) VALUES (450011,'Capricon_Mail_J','Capricon Mail','Armor',20,1000,100,1,true,1,true,'.@r = getrefine();\nbonus bUnbreakableArmor;\nbonus bMdef,5;\nbonus bBaseAtk,50;\nbonus bMatk,50;\nbonus bFlee2,3;\nbonus bMaxHP,1000;\nif (eaclass()&EAJL_THIRD && BaseJob == Job_Rogue) {\n   bonus bBaseAtk,80;\n   bonus bMatk,80;\n   bonus bMaxHPrate,10;\n   bonus bMaxSPrate,10;\n   if (.@r>=8)\n      bonus bUseSPrate,-20;\n}');
