REPLACE INTO `item_db_re` (`id`,`name_aegis`,`name_english`,`type`,`weight`,`defense`,`slots`,`location_armor`,`armor_level`,`equip_level_min`,`refineable`,`script`) VALUES (450128,'Auto_Armor_B','Automatic Armor Type B','Armor',1000,135,1,true,1,160,true,'.@r = getrefine();\nbonus bMatk,125+(10*(.@r/2));\nif (.@r>=7) {\n   bonus bVariableCastrate,-15;\n}');
REPLACE INTO `item_db_re` (`id`,`name_aegis`,`name_english`,`type`,`price_buy`,`weight`,`defense`,`slots`,`location_armor`,`armor_level`,`refineable`,`script`) VALUES (450129,'Aries_Mail_J','Aries Mail','Armor',20,1000,100,1,true,1,true,'.@r = getrefine();\nbonus bUnbreakableArmor;\nbonus bMdef,5;\nbonus bBaseAtk,50;\nbonus bMaxHP,1000;\nbonus bDelayrate,-10;\nif (eaclass()&EAJL_THIRD && BaseJob == Job_Crusader) {\n   bonus bBaseAtk,80;\n   bonus bMaxHPrate,10;\n   bonus bMaxSPrate,10;\n   if (.@r>=8)\n      bonus2 bSubClass,Class_Boss,5;\n}');
REPLACE INTO `item_db_re` (`id`,`name_aegis`,`name_english`,`type`,`price_buy`,`weight`,`defense`,`slots`,`location_armor`,`armor_level`,`refineable`,`script`) VALUES (450130,'Gemini_Mail_J','Gemini Mail','Armor',20,1000,100,1,true,1,true,'.@r = getrefine();\nbonus bUnbreakableArmor;\nbonus bMdef,5;\nbonus bBaseAtk,50;\nbonus bMatk,50;\nbonus bMaxHP,1000;\nbonus bDelayrate,-10;\nif ((eaclass()&EAJL_THIRD) && (BaseJob == Job_Bard || BaseJob == Job_Dancer)) {\n   bonus bBaseAtk,80;\n   bonus bMatk,80;\n   bonus bMaxHPrate,10;\n   bonus bMaxSPrate,10;\n   if (.@r>=8) {\n      bonus bAtkRate,30;\n      bonus bMatkRate,30;\n   }\n}');
REPLACE INTO `item_db_re` (`id`,`name_aegis`,`name_english`,`type`,`weight`,`defense`,`slots`,`location_armor`,`armor_level`,`equip_level_min`,`refineable`,`script`) VALUES (450131,'Fallen_Angel_Armor_TW','Fallen Angel Armor','Armor',1000,50,1,true,1,30,true,'.@r = getrefine();\nbonus bAllStats,1;\nbonus bUnbreakableArmor;\nbonus2 bSubEle,Ele_Holy,-10;\nbonus2 bSubRace,RC_Angel,-15;\nbonus2 bSubRace,RC_Demon,5+(.@r>=9?5:0);\nbonus2 bSubRace,RC_DemiHuman,5+(.@r>=9?5:0);\nbonus2 bSubRace,RC_Player_Human,5+(.@r>=9?5:0);\nbonus2 bSubRace,RC_Player_Doram,5+(.@r>=9?5:0);\nif (.@r>=7)\n   bonus bMaxHPrate,5;\nif (.@r>=11)\n   bonus bVariableCastrate,-8;');
REPLACE INTO `item_db_re` (`id`,`name_aegis`,`name_english`,`type`,`price_buy`,`weight`,`defense`,`slots`,`location_armor`,`armor_level`,`equip_level_min`,`refineable`,`script`) VALUES (450132,'Magical_Cloth','Magical Cloth','Armor',200000,100,45,1,true,1,100,true,'.@r = getrefine();\nbonus2 bMagicAtkEle,Ele_Earth,5;\nbonus2 bMagicAtkEle,Ele_Water,5;\nbonus2 bMagicAtkEle,Ele_Wind,5;\nbonus2 bMagicAtkEle,Ele_Fire,5;\nif (.@r>=7) {\n   bonus bAspdRate,10;\n   bonus2 bMagicAtkEle,Ele_Earth,2;\n   bonus2 bMagicAtkEle,Ele_Water,2;\n   bonus2 bMagicAtkEle,Ele_Wind,2;\n   bonus2 bMagicAtkEle,Ele_Fire,2;\n}\nif (.@r>=8) {\n   bonus bUnbreakableArmor;\n   bonus2 bMagicAtkEle,Ele_Earth,3;\n   bonus2 bMagicAtkEle,Ele_Water,3;\n   bonus2 bMagicAtkEle,Ele_Wind,3;\n   bonus2 bMagicAtkEle,Ele_Fire,3;\n}\nif (.@r>=9) {\n   bonus2 bMagicAtkEle,Ele_Earth,5;\n   bonus2 bMagicAtkEle,Ele_Water,5;\n   bonus2 bMagicAtkEle,Ele_Wind,5;\n   bonus2 bMagicAtkEle,Ele_Fire,5;\n   autobonus "{ bonus2 bSkillAtk,\\"MG_FIREBOLT\\",100; bonus2 bSkillAtk,\\"MG_COLDBOLT\\",100; bonus2 bSkillAtk,\\"MG_LIGHTNINGBOLT\\",100; bonus2 bSkillAtk,\\"WZ_EARTHSPIKE\\",100; }",2000,10000;\n}');
