REPLACE INTO `item_db_re` (`id`,`name_aegis`,`name_english`,`type`,`weight`,`slots`,`location_right_accessory`,`armor_level`,`equip_level_min`,`refineable`,`gradable`,`script`) VALUES (490276,'Dimmension_W_Key','Dimensional Wanderer\'s Key','Armor',200,1,true,2,240,true,true,'.@param = (readparam(bSpl)/20);\n.@g = getenchantgrade();\n.@r = getrefine();\nbonus bAllTraitStats,3;\nbonus bVariableCastrate,-10;\nif (.@r>=7) {\n   bonus bSMatk,3;\n   if (.@r>=9) {\n      bonus bSMatk,2*.@param;\n      bonus bWis,4*.@param;\n      if (.@r>=12) {\n         bonus bFixedCast,-300;\n      }\n   }\n}\nif (.@g>=ENCHANTGRADE_D) {\n   bonus bMatkRate,3;\n   bonus bSpl,2;\n   if (.@g>=ENCHANTGRADE_C) {\n      bonus bSMatk,2;\n      if (.@g>=ENCHANTGRADE_B) {\n         bonus bSMatk,3;\n         bonus bRes,20;\n         if (.@g>=ENCHANTGRADE_A) {\n            bonus bSpl,2*(readparam(bInt)/15);\n         }\n      }\n   }\n}');
